Item.method_code:
const { tabs, dockTabs, mainTabs, selectedTabs } =
	options.getState();

const { odataFetch } = ArasModules;
const viewTabs = JSON.stringify({
	tabs,
	dockTabs,
	mainTabs,
	selectedTabs
});
const itemId = aras.getPreferenceItemProperty('Core_GlobalLayout', null, 'id');
const requestUrl = `Core_GlobalLayout('${itemId}')`;
const { login_view_tabs: loginViewTabs } = await odataFetch(requestUrl, {
	method: 'PATCH',
	body: JSON.stringify({ login_view_tabs: viewTabs })
});

aras.setPreferenceItemProperties('Core_GlobalLayout', null, { login_view_tabs: loginViewTabs });

const notify = aras.getNotifyByContext(window);
const message = aras.getResource('', 'mainmenu.saved_login_view_tabs');
notify(message, { type: 'success' });
